98	async function fetchCoaches(f: CoachQueryFilters): Promise<Coach[]> {
99	  const params = new URLSearchParams();
100	  if (f.date && f.startTime && f.endTime) {
101	    params.set("date", f.date);
102	    params.set("startTime", f.startTime);
103	    params.set("endTime", f.endTime);
104	  }
105	  if (f.audiences?.length) params.set("audiences", f.audiences.join(","));
106	  if (f.travelPolicies?.length) params.set("travelPolicies", f.travelPolicies.join(","));
107	  if (f.cancellationPolicies?.length) params.set("cancellationPolicies", f.cancellationPolicies.join(","));
108	  if (f.city) params.set("city", f.city);
109	  if (f.sport) params.set("sport", f.sport);
110	  const r = await fetch(`${API}/coaches?${params.toString()}`);
111	  if (!r.ok) return [];
112	  return r.json();
113	}
