122	function addMinutes(hhmm: string, mins: number): string {
123	  const [h, m] = hhmm.split(":").map(Number);
124	  const total = h * 60 + m + mins;
125	  const hh = Math.floor(total / 60).toString().padStart(2, "0");
126	  const mm = (total % 60).toString().padStart(2, "0");
127	  return `${hh}:${mm}`;
128	}
