284	  const [searchDateObj, setSearchDateObj] = useState<Date | undefined>(undefined);
285	  const [searchDate, setSearchDate] = useState("");
286	  const dateRef = useRef<HTMLDivElement>(null);
287	
288	  // Time + duration — required by the availability matrix. When all three of
289	  // (date, time, duration) are present we pipe them to the /coaches endpoint
290	  // and the server filters by getCoachAvailability continuous coverage.
291	  const [searchTime, setSearchTime] = useState("");          // "HH:MM"
292	  const [searchDurationMin, setSearchDurationMin] = useState(60); // 30 | 60 | 90 | 120
293	  const [timeDropdownOpen, setTimeDropdownOpen] = useState(false);
294	  const timeRef = useRef<HTMLDivElement>(null);
295	
296	  // Filters — Strike-onboarding/marketplace
297	  const [activeAudiences, setActiveAudiences] = useState<Set<string>>(new Set());
298	  const [travelOnly, setTravelOnly] = useState(false);   // "atvyksta į mano aikštelę"
299	  const [flexibleOnly, setFlexibleOnly] = useState(false);
300	
301	  // Derived window for the API call. endTime exists only when all three are set.
302	  const effectiveEndTime = searchTime ? addMinutes(searchTime, searchDurationMin) : "";
303	  const windowReady = !!(searchDate && searchTime && effectiveEndTime);
304	
305	  // Time-of-day accent
306	  const [currentHour, setCurrentHour] = useState(() => new Date().getHours());
307	  useEffect(() => {
308	    const tick = setInterval(() => setCurrentHour(new Date().getHours()), 60_000);
309	    return () => clearInterval(tick);
310	  }, []);
311	  const TIME_PALETTES = [
312	    { color: "#38bdf8" }, // dawn
313	    { color: "#84cc16" }, // morning
314	    { color: "#f59e0b" }, // afternoon
315	    { color: "#f97316" }, // evening
316	    { color: "#8b5cf6" }, // night
317	  ];
318	  const timePalette =
319	    currentHour >= 5 && currentHour < 10 ? TIME_PALETTES[0] :
320	    currentHour >= 10 && currentHour < 14 ? TIME_PALETTES[1] :
321	    currentHour >= 14 && currentHour < 17 ? TIME_PALETTES[2] :
322	    currentHour >= 17 && currentHour < 21 ? TIME_PALETTES[3] :
323	    TIME_PALETTES[4];
324	  const timeAccent = timePalette.color;
325	  const accentColor = searchSport ? (sportColor[searchSport] ?? timeAccent) : timeAccent;
326	  function contrastText(hex: string) {
327	    const r = parseInt(hex.slice(1,3),16), g = parseInt(hex.slice(3,5),16), b = parseInt(hex.slice(5,7),16);
328	    return (0.299*r + 0.587*g + 0.114*b) / 255 > 0.55 ? "#000" : "#fff";
329	  }
330	  const accentFg = contrastText(accentColor);
331	
332	  // Close dropdowns on outside click
333	  useEffect(() => {
334	    function handleClick(e: MouseEvent) {
335	      if (cityRef.current && !cityRef.current.contains(e.target as Node)) setCityDropdownOpen(false);
336	      if (dateRef.current && !dateRef.current.contains(e.target as Node)) setDateDropdownOpen(false);
337	      if (timeRef.current && !timeRef.current.contains(e.target as Node)) setTimeDropdownOpen(false);
338	    }
339	    document.addEventListener("mousedown", handleClick);
340	    return () => document.removeEventListener("mousedown", handleClick);
341	  }, []);
342	
343	  // Cities from courts API
344	  const { data: courts } = useListCourts(undefined, { query: { queryKey: getListCourtsQueryKey(), staleTime: 60_000 } });
345	  const uniqueCities = [...new Set((courts ?? []).map(c => c.city).filter((c): c is string => !!c))].sort();
346	  const cityCounts = (courts ?? []).reduce<Record<string, number>>((acc, c) => {
347	    if (c.city) acc[c.city] = (acc[c.city] ?? 0) + 1;
348	    return acc;
349	  }, {});
