351	  const popularCities = [...uniqueCities].sort((a, b) => (cityCounts[b] ?? 0) - (cityCounts[a] ?? 0)).slice(0, TOP_N);
352	  const otherCities = uniqueCities.filter(c => !popularCities.includes(c));
353	  const cityFilter = cityInput.trim().toLowerCase();
