377	  );
378	  const [maxPrice, setMaxPrice] = useState(200);
379	  const [sortBy, setSortBy] = useState<"default" | "price_asc" | "price_desc" | "rating_desc">("default");
380	  const [mobileFiltersOpen, setMobileFiltersOpen] = useState(false);
381	  const [cityExpanded, setCityExpanded] = useState(false);
382	  const [page, setPage] = useState(1);
383	  const [viewMode, setViewMode] = useState<"list" | "map">("list");
384	
385	  // Sync hero sport pill → sidebar
386	  useEffect(() => {
387	    if (searchSport) {
388	      setActiveSports(new Set([searchSport]));
389	    } else {
390	      setActiveSports(new Set(ALL_SPORTS));
391	    }
392	  }, [searchSport]);
393	
394	  useEffect(() => {
395	    setPage(1);
396	  }, [search, activeSports, maxPrice, sortBy, searchCity, searchDate, searchTime, searchDurationMin, activeAudiences, travelOnly, flexibleOnly]);
397	
398	  const allSportsActive = activeSports.size === ALL_SPORTS.length;
399	  // Single-select sport filter: clicking a sport narrows to JUST that sport
400	  // in one click. Clicking the currently-only-selected sport widens back to
401	  // "all sports active" (the unfiltered state). No multi-select — the user
402	  // explicitly asked for "filtering by sport should be one click only".
403	  const toggleSport = (sport: string) => {
404	    setActiveSports(prev => {
405	      if (prev.size === 1 && prev.has(sport)) {
406	        return new Set(ALL_SPORTS);
407	      }
408	      return new Set([sport]);
409	    });
410	  };
411	  const resetSports = () => setActiveSports(new Set(ALL_SPORTS));
412	
413	  const filteredCoaches = (coaches ?? []).filter(c => {
414	    const matchesSearch = !search.trim() ||
415	      c.name.toLowerCase().includes(search.toLowerCase()) ||
416	      (c.bio ?? "").toLowerCase().includes(search.toLowerCase());
417	    const matchesSport = activeSports.size === ALL_SPORTS.length || c.sports.some(s => activeSports.has(s));
418	    // maxPrice is euros from the slider; coach.pricePerHour is integer cents.
419	    const matchesPrice = c.pricePerHour == null || c.pricePerHour <= maxPrice * 100;
420	    const matchesCity = !searchCity || (c.cities ?? []).some(
421	      city => city.toLowerCase() === searchCity.toLowerCase()
422	    );
423	    return matchesSearch && matchesSport && matchesPrice && matchesCity;
424	  });
425	
426	  const sortedCoaches = [...filteredCoaches].sort((a, b) => {
427	    if (sortBy === "rating_desc") return ((b as any).rating ?? 0) - ((a as any).rating ?? 0);
428	    if (sortBy === "price_asc") return (a.pricePerHour ?? 999) - (b.pricePerHour ?? 999);
429	    if (sortBy === "price_desc") return (b.pricePerHour ?? 0) - (a.pricePerHour ?? 0);
430	    return 0;
431	  });
432	
433	  const total = sortedCoaches.length;
434	  const totalPages = Math.max(1, Math.ceil(total / PAGE_SIZE));
435	  const paged = sortedCoaches.slice((page - 1) * PAGE_SIZE, page * PAGE_SIZE);
436	
437	  const activeFilterCount = [
438	    activeSports.size < ALL_SPORTS.length,
