440	    search.trim().length > 0,
441	    activeAudiences.size > 0,
442	    travelOnly,
443	    flexibleOnly,
444	  ].filter(Boolean).length;
445	
446	  const resetFilters = () => {
447	    setActiveSports(new Set(ALL_SPORTS));
448	    setMaxPrice(200);
449	    setSearch("");
450	    setSortBy("default");
451	    setActiveAudiences(new Set());
452	    setTravelOnly(false);
453	    setFlexibleOnly(false);
454	  };
