  const today = new Date(new Date().setHours(0, 0, 0, 0));
  const stripDates = Array.from({ length: 7 }, (_, i) => addDays(today, i));
  const isInStrip = stripDates.some(d => isSameDay(d, date));
  return (
    <div className="flex-1 flex gap-2 overflow-x-auto pb-1 -mx-0.5 px-0.5 [&::-webkit-scrollbar]:hidden [-ms-overflow-style:none] [scrollbar-width:none]">
      {/* Selected far-date chip — only appears when user picked
          a date outside the 7-day window via the popover. Keeps
          the selection visible so they always know what's set. */}
      {!isInStrip && (
        <button
          type="button"
          onClick={() => setCalendarOpen(true)}
          className="shrink-0 min-w-[78px] rounded-xl border border-primary bg-primary/10 text-primary px-2.5 py-2 text-center transition-colors"
          aria-pressed
          title="Keisti datą"
        >
          <div className="text-[10px] font-semibold uppercase tracking-wide text-primary truncate">
            {format(date, "EEE", { locale: ltLocale })}
          </div>
          <div className="text-sm font-semibold leading-tight mt-0.5">
            {format(date, "MMM d", { locale: ltLocale })}
          </div>
        </button>
      )}
      {stripDates.map((d, i) => {
        const isSelected = isSameDay(d, date);
        const topLabel =
          i === 0
            ? "Šiandien"
